// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    MockERC20 baseAsset;
    EIP1271Maker maker;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        baseAsset = new MockERC20();
        maker = new EIP1271Maker();
    }

    function testFuzz_property(address taker, uint256 strike, uint256 premium, uint256 duration) public {
        vm.assume(taker != address(0) && taker != address(maker));
        strike = bound(strike, 1, type(uint128).max);
        premium = bound(premium, 1, type(uint128).max);
        duration = bound(duration, 1, 10_000 days - 1);

        vm.warp(1_700_000_000);

        address[] memory emptyAddrs = new address[](0);
        PuttyV2.ERC20Asset[] memory emptyE20 = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory emptyE721 = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: false,
            isLong: false,
            baseAsset: address(baseAsset),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: block.timestamp + 1,
            nonce: 0,
            whitelist: emptyAddrs,
            floorTokens: emptyAddrs,
            erc20Assets: emptyE20,
            erc721Assets: emptyE721
        });

        uint256[] memory noFloors = new uint256[](0);

        vm.prank(taker);
        uint256 positionId = c.fillOrder(order, "", noFloors);

        // General rule: a successful fill of a valid short-put order mints and returns
        // the taker's position id, i.e. uint256(hashOppositeOrder(order)), with the
        // taker as its owner and its expiration set to block.timestamp + duration.
        assertTrue(
            positionId == uint256(c.hashOppositeOrder(order)) &&
            c.ownerOf(positionId) == taker &&
            c.positionExpirations(positionId) == block.timestamp + duration
        );
    }
}

contract EIP1271Maker {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}

contract MockERC20 {
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
}
